**What this code covers**

- Video search using Elasticsearch + ML-based recommendations
- Full-text search with relevance ranking Uses Elasticsearch with custom scoring
- Search videos with multi-field matching and boosting
- ML-based video recommendation system
- Check cache for popular queries
- Cache popular searches for 5 minutes
- Generate candidates from multiple sources
- 1. Subscription feed (30%)

**Defines:** `SearchResult`, `VideoSearchService`, `VideoRecommendationEngine`

```python
"""
Video search using Elasticsearch + ML-based recommendations
"""

from dataclasses import dataclass
from typing import List, Dict, Optional
import time

@dataclass
class SearchResult:
    video_id: str
    title: str
    channel_name: str
    thumbnail_url: str
    duration: int
    views: int
    published_at: str
    relevance_score: float

class VideoSearchService:
    """
    Full-text search with relevance ranking
    Uses Elasticsearch with custom scoring
    """

    def __init__(self, es_client, cache):
        self.es = es_client
        self.cache = cache

    def search(self, query: str, filters: dict = None,
               page: int = 1, page_size: int = 20) -> dict:
        """
        Search videos with multi-field matching and boosting
        """
        # Check cache for popular queries
        cache_key = f"search:{hash(query)}:{page}"
        cached = self.cache.get(cache_key)
        if cached:
            return cached

        # Build Elasticsearch query
        es_query = {
            "bool": {
                "must": [
                    {
                        "multi_match": {
                            "query": query,
                            "fields": [
                                "title^3",          # Title gets 3x boost
                                "description^1.5",   # Description 1.5x
                                "tags^2",            # Tags 2x
                                "channel_name^2",    # Channel name 2x
                                "captions"           # Auto-generated captions
                            ],
                            "type": "best_fields",
                            "fuzziness": "AUTO"
                        }
                    }
                ],
                "filter": [],
                "should": [
                    # Boost recent videos
                    {
                        "range": {
                            "published_at": {
                                "gte": "now-7d",
                                "boost": 2.0
                            }
                        }
                    },
                    # Boost popular videos
                    {
                        "range": {
                            "views": {
                                "gte": 100000,
                                "boost": 1.5
                            }
                        }
                    }
                ]
            }
        }

        # Apply filters
        if filters:
            if filters.get("duration"):
                if filters["duration"] == "short":
                    es_query["bool"]["filter"].append(
                        {"range": {"duration": {"lte": 240}}}
                    )
                elif filters["duration"] == "long":
                    es_query["bool"]["filter"].append(
                        {"range": {"duration": {"gte": 1200}}}
                    )

            if filters.get("upload_date"):
                es_query["bool"]["filter"].append(
                    {"range": {"published_at": {"gte": f"now-{filters['upload_date']}"}}}
                )

        # Execute search
        results = self.es.search(
            index="videos",
            body={
                "query": es_query,
                "from": (page - 1) * page_size,
                "size": page_size,
                "sort": [
                    "_score",
                    {"views": "desc"}
                ],
                "highlight": {
                    "fields": {
                        "title": {},
                        "description": {"fragment_size": 200}
                    }
                }
            }
        )

        response = {
            "total": results["hits"]["total"]["value"],
            "page": page,
            "results": [
                SearchResult(
                    video_id=hit["_source"]["video_id"],
                    title=hit["_source"]["title"],
                    channel_name=hit["_source"]["channel_name"],
                    thumbnail_url=hit["_source"]["thumbnail_url"],
                    duration=hit["_source"]["duration"],
                    views=hit["_source"]["views"],
                    published_at=hit["_source"]["published_at"],
                    relevance_score=hit["_score"]
                ).__dict__
                for hit in results["hits"]["hits"]
            ]
        }

        # Cache popular searches for 5 minutes
        self.cache.setex(cache_key, 300, response)
        return response

class VideoRecommendationEngine:
    """
    ML-based video recommendation system

    Sources:
    1. Collaborative filtering (users who watched X also watched Y)
    2. Content-based (similar titles, tags, descriptions)
    3. Trending/popular videos
    4. User history and preferences
    """

    def __init__(self, ml_model, user_service, video_service, cache):
        self.model = ml_model
        self.user_service = user_service
        self.video_service = video_service
        self.cache = cache

    def get_home_feed(self, user_id: str, page: int = 1) -> List[dict]:
        """
        Generate personalized home feed
        Mix of: recommended, subscriptions, trending, new
        """
        # Get user profile
        user = self.user_service.get_user(user_id)
        watch_history = self.user_service.get_watch_history(user_id, limit=100)
        subscriptions = self.user_service.get_subscriptions(user_id)

        # Generate candidates from multiple sources
        candidates = []

        # 1. Subscription feed (30%)
        sub_videos = self._get_subscription_videos(subscriptions, limit=30)
        candidates.extend([(v, "subscription", 0.3) for v in sub_videos])

        # 2. Collaborative filtering recommendations (30%)
        cf_videos = self._collaborative_filter(user_id, watch_history, limit=30)
        candidates.extend([(v, "collaborative", 0.3) for v in cf_videos])

        # 3. Content-based recommendations (20%)
        cb_videos = self._content_based_recommend(watch_history, limit=20)
        candidates.extend([(v, "content_based", 0.2) for v in cb_videos])

        # 4. Trending (20%)
        trending = self._get_trending(user.get("country", "US"), limit=20)
        candidates.extend([(v, "trending", 0.2) for v in trending])

        # Deduplicate and rank
        seen_ids = set(h["video_id"] for h in watch_history)
        unique_candidates = []
        seen = set()

        for video, source, weight in candidates:
            vid = video["video_id"]
            if vid not in seen and vid not in seen_ids:
                video["source"] = source
                video["weight"] = weight
                unique_candidates.append(video)
                seen.add(vid)

        # Score and sort
        scored = self._rank_candidates(unique_candidates, user)

        # Paginate
        start = (page - 1) * 20
        return scored[start:start + 20]

    def get_related_videos(self, video_id: str, limit: int = 20) -> List[dict]:
        """Get videos related to currently watching video"""

        cache_key = f"related:{video_id}"
        cached = self.cache.get(cache_key)
        if cached:
            return cached

        video = self.video_service.get_video(video_id)

        # Find similar by content features
        similar = self.model.find_similar(
            title=video["title"],
            tags=video["tags"],
            category=video["category"],
            channel_id=video["channel_id"],
            limit=limit
        )

        self.cache.setex(cache_key, 1800, similar)  # Cache 30 min
        return similar

    def _collaborative_filter(self, user_id: str,
                                history: list, limit: int) -> list:
        """Find videos watched by similar users"""
        # In production: Matrix factorization or deep learning model
        similar_users = self.model.find_similar_users(user_id, limit=50)

        videos = []
        for similar_user in similar_users:
            their_history = self.user_service.get_watch_history(
                similar_user["user_id"], limit=20
            )
            videos.extend(their_history)

        # Rank by frequency across similar users
        video_counts = {}
        for v in videos:
            vid = v["video_id"]
            video_counts[vid] = video_counts.get(vid, 0) + 1

        sorted_videos = sorted(video_counts.items(), key=lambda x: -x[1])
        return [{"video_id": vid} for vid, _ in sorted_videos[:limit]]

    def _rank_candidates(self, candidates: list, user: dict) -> list:
        """Score candidates using ML model features"""
        for video in candidates:
            features = {
                "user_interest_score": self._calc_interest(video, user),
                "recency_score": self._calc_recency(video),
                "popularity_score": min(video.get("views", 0) / 1_000_000, 1.0),
                "source_weight": video.get("weight", 0.1),
                "channel_affinity": self._calc_channel_affinity(
                    video.get("channel_id"), user
                )
            }
            video["score"] = sum(features.values()) / len(features)

        candidates.sort(key=lambda v: v["score"], reverse=True)
        return candidates

    def _calc_interest(self, video: dict, user: dict) -> float:
